s=s[:start]+'''<section class="hero playful-hero"><div class="shell hero-layout"><div class="hero-copy"><p class="eyebrow eyebrow--dot"><i></i>BOIT 2.0 / A new chapter</p><h1>Insurance.<br><span class="gradient-text">Reimagined.</span></h1><p class="hero-lede">Big ideas for simpler insurance.<br>Meet the motor, medical, and life products we’re building to move the industry forward.</p><div class="hero-actions"><a class="btn btn--primary" href="#boit2">Meet the products <span>↗</span></a><a class="hero-new" href="#roadmap">Let’s talk <span>→</span></a></div><div class="hero-tags"><span><i></i>Three planned products</span><span>One connected vision</span></div></div><div class="hero-playground" aria-label="BOIT 2.0 motor, medical and life products"><div class="playground-grid"></div><div class="halo halo-one"></div><div class="halo halo-two"></div><div class="central-orb"><span>bo<span>IT</span></span><small>2.0</small></div><a href="#product-motor" class="floating-product float-motor"><span class="float-icon">↗</span><span><small>MOTOR INSURANCE</small><strong>Motor360</strong></span><span class="float-arrow">→</span></a><a href="#product-medical" class="floating-product float-medical"><span class="float-icon">+</span><span><small>MEDICAL INSURANCE</small><strong>Medical360</strong></span><span class="float-arrow">→</span></a><a href="#product-life" class="floating-product float-life"><span class="float-icon">♡</span><span><small>LIFE INSURANCE</small><strong>Life360</strong></span><span class="float-arrow">→</span></a><span class="spark spark-one">✳</span><span class="spark spark-two">✧</span><span class="concept-tag">THE NEXT CHAPTER IS TAKING SHAPE</span></div></div><div class="hero-bottom shell"><span>SCROLL TO EXPLORE ↓</span><span>MOTOR / MEDICAL / LIFE</span></div></section>'''+s[end:]
for slug in ['motor','medical','life']:
 s=s.replace(f'<article class="product-card {slug}">',f'<article id="product-{slug}" class="product-card {slug}">')
s=s.replace('<div class="product-grid">','<div class="product-jump"><a href="#product-motor">01 <b>Motor</b> ↗</a><a href="#product-medical">02 <b>Medical</b> ↗</a><a href="#product-life">03 <b>Life</b> ↗</a></div><div class="product-grid">')
s=s.replace('<p class="eyebrow eyebrow--accent">BOIT 2.0 — Products in development</p>','<p class="eyebrow eyebrow--accent">01 / Meet the next generation</p>')
s=s.replace('Three products.<br>Built around the insurance<br class="desktop-break"> journeys that matter.','Three products.<br><span class="gradient-text">A world of possibility.</span>')
s=s.replace('<section class="panel-light"><div class="section"><p class="eyebrow">02 — Module inventory</p>','<section class="panel-light"><div class="section"><details class="inventory-details"><summary><span class="eyebrow">Explore the wider platform</span><span class="details-label">Engagement, operations & distribution <b>+</b></span></summary><div class="inventory-body"><p class="eyebrow">02 — Module inventory</p>')
s=s.replace('</div></section><section class="section"><p class="eyebrow">03 — Intelligence layer','</div></details></div></section><section class="section"><p class="eyebrow">03 — Intelligence layer')
s=s.replace('Be part of<br>what comes next.','Let’s shape<br><span class="gradient-text">what’s next.</span>')
